                    if not (0 <= nr < h and 0 <= nc < w) or (nr, nc) in seen:
                        continue
                    if grid[nr][nc] == wall:
                        continue
                    # Diagonal lines are continuous walls: do not cut their corners.
                    if dr and dc and (grid[r + dr][c] == wall or grid[r][c + dc] == wall):
                        continue
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return seen

    candidates = []
    done = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or grid[r][c] == wall or (r, c) in done:
                continue
            reg = region(r, c)
            done.update(reg)
            candidates.append((len(reg), grid[r][c], reg))
    if not candidates:
        return [row[:] for row in grid]
    _, color, reg = min(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for r, c in reg:
